/** Where everything sits on the film's clock. */
export interface Placed { kind: 'transition'; id: TransitionId; at: number; dur: number; prev?: ChapterSpec; next: ChapterSpec; cards?: LunchRow[] }
export interface PlacedChapter { kind: 'chapter'; spec: ChapterSpec; at: number; dur: number; offset: number }

export const layout = () => {
  const out: (Placed | PlacedChapter)[] = [];
  let at = 0;
  let prev: ChapterSpec | undefined;
  for (const { before, spec, cards } of CHAPTERS) {
    // Two transitions back to back (heads down, then the sounds interstitial) share the gap.
    for (const id of Array.isArray(before) ? before : [before]) {
      out.push({ kind: 'transition', id, at, dur: T_DUR[id], prev, next: spec, cards });
      at += T_DUR[id];
    }
    const dur = spec.to - spec.from;
    // offset: take frame = film frame - offset
    out.push({ kind: 'chapter', spec, at, dur, offset: at - spec.from });
    at += dur;
    prev = spec;
  }
  return { parts: out, end: at };
};

export const timeline = (c: Clock): CueSheet => {
  const { parts, end } = layout();
  const lockup = end;
  const total = lockup + Math.round(c.bar * 2);
  const lines: Line[] = [];
  const cues: Cue[] = [];
  for (const p of parts) {
    if (p.kind !== 'chapter') continue;
    const { spec, offset, at, dur } = p;
    const t = TRACKS[spec.take];
    for (const s of spec.say) {
      const mark = t.marks[s.mark];
      if (mark === undefined) continue;
      const from = mark + offset + (s.delay ?? 0);
      if (from < at || from >= at + dur) continue;
      const to = Math.min(at + dur - 4, from + (s.hold ?? 120));
      lines.push({ id: `${spec.id}:${s.mark}`, from, to, text: s.text, place: s.place ?? 'tile', pin: s.pin, tone: s.tone, icon: s.icon });
    }
    // the app's own sounds where its agents did something: an agent finishing its turn (bloom),
    // a push (orbit) and a merge (prism), as the app plays them with sounds on (AgentSoundRules)
    const appSounds: [string, Cue['sfx']][] = [['planned', 'bloom'], ['pushed', 'orbit'], ['merged', 'prism'], ['subsDone', 'bloom'],
      ['shipped', 'bloom'], ['cartDone', 'bloom'], ['darkDone', 'bloom'], ['cartDone2', 'bloom'],
      ['pickPushPreview', 'orbit'], ['pickMergePreview', 'prism']];
    for (const [mark, sfx] of appSounds) {
      const f = t.marks[mark] === undefined ? undefined : t.marks[mark] + offset;
      if (f !== undefined && f >= at && f < at + dur) cues.push({ id: `${spec.id}:${mark}`, at: f, sfx });
    }
    // the hand's presses and drops, in the take, as heard
    for (const e of t.events) {
      const f = e.frame + offset;
      if (f < at || f >= at + dur) continue;
      if (e.type === 'press') cues.push({ id: `${spec.id}:press${e.frame}`, at: f, sfx: 'click' });
      if (e.type === 'drop') cues.push({ id: `${spec.id}:drop${e.frame}`, at: f, sfx: 'thud' });
    }
  }
  for (const l of lines) cues.push({ id: `pop:${l.id}`, at: l.from, sfx: 'pop' });
  lines.push({ id: 'promise', from: lockup + Math.round(c.beat * 1.5), to: total, text: 'Keep every agent in view.', place: 'lockup', size: 'hook' });
  lines.push({ id: 'where', from: lockup + Math.round(c.bar), to: total, text: 'arrayapp.dev · Free during alpha · macOS 14+', place: 'lockup' });
  cues.push({ id: 'lockup', at: lockup, sfx: 'whoosh' }, { id: 'mark', at: lockup + Math.round(c.beat / 2), sfx: 'bell' });
  const acts: CueSheet['acts'] = {};
  const names: Record<string, string> = { sunrise: 'sunrise', coffee: 'coffee', lunch: 'lunch', headsdown: 'headsdown', sounds: 'sounds', sunset: 'sunset', morning: 'morning', late: 'late', afternoon: 'afternoon', ship: 'peak', evening: 'evening' };
  for (const p of parts) {
    const id = p.kind === 'transition' ? p.id : p.spec.id;
    acts[names[id] ?? id] = { name: id, from: p.at, dur: p.dur };
  }
  acts.lockup = { name: 'lockup', from: lockup, dur: total - lockup };
  return { slug: 'full-day', title: 'A day in Array', clock: c, durationInFrames: total, music: 'day', acts, cues, tracks: [], lens: [], lines, chapters: [], overlays: [] };
};
